class Solution {
public:
    vector<int> findMissingAndRepeatedValues(vector<vector<int>>& grid) {
        int n = grid.size();
        long long N = n * n;
        long long sum_grid = 0, sum_sq_grid = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                long long val = grid[i][j];
                sum_grid += val;
                sum_sq_grid += val * val;
            }
        }

        long long sum_exp = N * (N + 1) / 2;
        long long sum_sq_exp = N * (N + 1) * (2 * N + 1) / 6;

        long long diff1 = sum_grid - sum_exp; // a - b
        long long diff2 = sum_sq_grid - sum_sq_exp; // a^2 - b^2

        long long sum_ab = diff2 / diff1; // a + b

        long long a = (diff1 + sum_ab) / 2;
        long long b = (sum_ab - diff1) / 2;

        return {(int)a, (int)b};
    }
};
